def replace_words(dictionary, sentence):
    root_trie = {}
    END = '$'
    for root in dictionary:
        node = root_trie
        for ch in root:
            node = node.setdefault(ch, {})
        node[END] = True

    def shortest_root(word):
        node = root_trie
        prefix = []
        for ch in word:
            if ch not in node:
                return word
            prefix.append(ch)
            node = node[ch]
            if END in node:
                return ''.join(prefix)
        return word

    return ' '.join(shortest_root(w) for w in sentence.split(' '))

